import{_ as a,o,c as t,a2 as r}from"./chunks/framework.C9_66ieh.js";const m=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":1785285552000}'),n={name:"glossary.md"};function s(d,e,i,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Terms used in TrueDeck docs and UI.</p><h2 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h2><p>A coding CLI preset (Grok, Codex, Cursor Agent, Claude, …) or a plain shell. Spawned as a PTY session, not an in-process model SDK.</p><h2 id="agent-frame-frame-tui" tabindex="-1">Agent frame / frame TUI <a class="header-anchor" href="#agent-frame-frame-tui" aria-label="Permalink to &quot;Agent frame / frame TUI&quot;">​</a></h2><p>In-terminal chrome (<code>truedeck-frame.mjs</code>) that reserves a header band above the child agent TUI. Controlled by <code>agentFrameTui</code> / <code>frameShellPanes</code>. See <a href="./agent-frame">Agent frame</a>.</p><h2 id="aptint" tabindex="-1">AptInt <a class="header-anchor" href="#aptint" aria-label="Permalink to &quot;AptInt&quot;">​</a></h2><p><strong>Not used in TrueDeck.</strong> AptInt is an arbitrary-precision integer type from other projects (e.g. SPTS Roblox stats). TrueDeck does not implement AptInt.</p><h2 id="auto-context" tabindex="-1">Auto-context <a class="header-anchor" href="#auto-context" aria-label="Permalink to &quot;Auto-context&quot;">​</a></h2><p>Generated markdown at <code>.truedeck/auto-context.md</code> summarizing project memory pointers for agents. Refreshed on project open / agent spawn.</p><h2 id="backend-rust" tabindex="-1">Backend (Rust) <a class="header-anchor" href="#backend-rust" aria-label="Permalink to &quot;Backend (Rust)&quot;">​</a></h2><p>Primary <code>truedeck-backend</code> process owning PTY and related RPC. See <a href="./RUST-BACKEND">RUST-BACKEND.md</a>.</p><h2 id="tasks-launch" tabindex="-1">Tasks / launch <a class="header-anchor" href="#tasks-launch" aria-label="Permalink to &quot;Tasks / launch&quot;">​</a></h2><p>Task records + MCP launch (<code>truedeck_launch</code>) that dispatch to real agent PTYs. No board UI - see <a href="./task-board">Task board</a> and <a href="./mcp">MCP</a>.</p><h2 id="command-session" tabindex="-1">Command session <a class="header-anchor" href="#command-session" aria-label="Permalink to &quot;Command session&quot;">​</a></h2><p>A PTY started from an on-open or ad-hoc shell command (<code>kind: &#39;command&#39;</code>), not a named agent preset. Framed only if <code>frameShellPanes</code> is on.</p><h2 id="dispatch" tabindex="-1">Dispatch <a class="header-anchor" href="#dispatch" aria-label="Permalink to &quot;Dispatch&quot;">​</a></h2><p>Spawning an agent for a board task: write task file, set env, create run, seed prompt. Implemented in <code>task-dispatch.ts</code>.</p><h2 id="group-pane-group" tabindex="-1">Group (pane group) <a class="header-anchor" href="#group-pane-group" aria-label="Permalink to &quot;Group (pane group)&quot;">​</a></h2><p>A leaf in the pane tree: its own tab bar and active tab. Multiple groups appear side-by-side or stacked after a split.</p><h2 id="hub-mcp-hub" tabindex="-1">Hub (MCP hub) <a class="header-anchor" href="#hub-mcp-hub" aria-label="Permalink to &quot;Hub (MCP hub)&quot;">​</a></h2><p>Unified MCP configuration managed by TrueDeck and synced to agent clients. Built-in server id <code>truedeck-hub</code>. See <a href="./mcp">MCP</a>.</p><h2 id="leaf" tabindex="-1">Leaf <a class="header-anchor" href="#leaf" aria-label="Permalink to &quot;Leaf&quot;">​</a></h2><p>A pane-tree node that holds tab indices and an active tab (not a split).</p><h2 id="memory-truememory" tabindex="-1">Memory / TrueMemory <a class="header-anchor" href="#memory-truememory" aria-label="Permalink to &quot;Memory / TrueMemory&quot;">​</a></h2><p>Markdown notes under <code>.memory/</code> (repo) and the global memory directory. Always available offline. Distinct from MemPalace graph storage.</p><h2 id="mempalace-palace" tabindex="-1">MemPalace / palace <a class="header-anchor" href="#mempalace-palace" aria-label="Permalink to &quot;MemPalace / palace&quot;">​</a></h2><p>Native memory backend (graph/vector palace) when enabled. Path often <code>~/.mempalace/palace</code> or Settings <code>palacePath</code>. See <a href="./memory-providers">memory-providers.md</a>.</p><h2 id="on-open-command" tabindex="-1">On-open command <a class="header-anchor" href="#on-open-command" aria-label="Permalink to &quot;On-open command&quot;">​</a></h2><p>Shell command associated with a project that can spawn when the project opens (e.g. <code>rojo serve</code>).</p><h2 id="pane" tabindex="-1">Pane <a class="header-anchor" href="#pane" aria-label="Permalink to &quot;Pane&quot;">​</a></h2><p>A rectangular terminal region (leaf group). Splits create more panes up to 16.</p><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><p>A tracked folder (<code>ProjectConfig</code>) with root path, recents, on-open commands, and default agents.</p><h2 id="pty" tabindex="-1">PTY <a class="header-anchor" href="#pty" aria-label="Permalink to &quot;PTY&quot;">​</a></h2><p>Pseudo-terminal hosting an agent or shell. Engines: node-pty or Rust sidecars.</p><h2 id="resolve-resolve-command" tabindex="-1">Resolve / resolve-command <a class="header-anchor" href="#resolve-resolve-command" aria-label="Permalink to &quot;Resolve / resolve-command&quot;">​</a></h2><p>Mapping agent id + command name to an on-disk executable, with IDE blocking for Cursor. See <a href="./agents">Agents</a>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>A recorded agent execution linked to a task (<code>AgentRun</code>: start/end times, exit code, session id).</p><h2 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h2><p>A live (or exited) PTY instance tracked as <code>SessionInfo</code> with agent metadata and project root.</p><h2 id="session-layout" tabindex="-1">Session layout <a class="header-anchor" href="#session-layout" aria-label="Permalink to &quot;Session layout&quot;">​</a></h2><p>Persisted snapshot of tabs + pane tree (<code>session-layout.json</code>) used for restore.</p><h2 id="split" tabindex="-1">Split <a class="header-anchor" href="#split" aria-label="Permalink to &quot;Split&quot;">​</a></h2><p>A pane-tree node with direction (<code>row</code> / <code>column</code>), ratio, and two children. Created via <strong>Ctrl+D</strong> (vertical) / <strong>Ctrl+X</strong> (horizontal) or drag-drop.</p><h2 id="studio-ui" tabindex="-1">Studio UI <a class="header-anchor" href="#studio-ui" aria-label="Permalink to &quot;Studio UI&quot;">​</a></h2><p>Electron + React + xterm interface (<code>npm start</code>). Contrasts with the Blessed TUI (<code>npm run tui</code>).</p><h2 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h2><p>Kanban card (<code>Task</code>) with status, assignee agent, and session/run links when present.</p><h2 id="tui" tabindex="-1">TUI <a class="header-anchor" href="#tui" aria-label="Permalink to &quot;TUI&quot;">​</a></h2><ol><li>TrueDeck’s terminal-only app mode</li><li>Any agent’s full-screen terminal UI (Codex, Claude Code, …)</li></ol><h2 id="wing" tabindex="-1">Wing <a class="header-anchor" href="#wing" aria-label="Permalink to &quot;Wing&quot;">​</a></h2><p>MemPalace naming concept: a project-scoped area inside the palace (<code>TRUEDECK_MEMORY_WING</code>).</p><h2 id="xterm" tabindex="-1">xterm <a class="header-anchor" href="#xterm" aria-label="Permalink to &quot;xterm&quot;">​</a></h2><p>The browser terminal emulator in the renderer (<code>xterm</code> + Fit / WebLinks addons) attached to PTY data over IPC.</p>',56)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
